window.products.push({"id":279531,"name":"Allied Metal 17-Inch Hard Aluminum Traditional Wide Rim Style Perforated Pizza Tray","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/418wHC3q5PL._AC_.jpg","description":"Standard traditional wide rim style perforated pizza tray made of hard 18 gauge aluminum. Use of this perforated style pan results in a more evenly baked crust, as it enables air to circulate between the product being baked and the underlying oven. Ideal for baking or reheating pizza. This high grade commercial quality product is great for home or commercial use. Made in the USA by Allied Metal. 17\" diameter (189 holes).","images":["https://m.media-amazon.com/images/I/418wHC3q5PL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Allied Metal","source_asin":"B0055DJ40E","category_path":"Home & Kitchen"},"sku":"BM-279531","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0055DJ40E","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0055DJ40E","price_pending":true,"merchant_ready":false});
